function v25_code(string $c):string{return '<pre style="background:#f4f5f7;border:1px solid #d8dce1;padding:1em;overflow:auto"><code>'.s($c).'</code></pre>';}
function v25_q(string $id,string $prompt,array $choices,int $correct,string $explanation):array{return compact('id','prompt','choices','correct','explanation');}
function v25_save(int $cat,int $ctx,string $prefix,array $d,string $lang):stdClass{
    $q=(object)['qtype'=>'multichoice','category'=>$cat.','.$ctx];$a=$f=$r=[];
    foreach($d['choices'] as $i=>[$text,$why]){$a[]=['text'=>$text,'format'=>FORMAT_PLAIN];$f[]=['text'=>'<p>'.s($why).'</p>','format'=>FORMAT_HTML];$r[]=$i===$d['correct']?1.0:0.0;}
    $form=(object)['name'=>$prefix.$d['id'],'category'=>$cat.','.$ctx,'questiontext'=>['text'=>$d['prompt'],'format'=>FORMAT_HTML],
      'generalfeedback'=>['text'=>'<p><strong>'.($lang==='ja'?'学習ポイント：':'Learning point:').'</strong> '.s($d['explanation']).'</p>','format'=>FORMAT_HTML],
      'defaultmark'=>10,'penalty'=>0.3333333,'status'=>question_version_status::QUESTION_STATUS_READY,'idnumber'=>null,'single'=>1,'shuffleanswers'=>1,'answernumbering'=>'abc','showstandardinstruction'=>1,
      'correctfeedback'=>['text'=>$lang==='ja'?'<p>正解です。集計単位、件数、分母、照合を結び付けて進みましょう。</p>':'<p>Correct. Connect grain, count, denominator, and reconciliation.</p>','format'=>FORMAT_HTML],
      'partiallycorrectfeedback'=>['text'=>'','format'=>FORMAT_HTML],'incorrectfeedback'=>['text'=>$lang==='ja'?'<p>結果の一行が何を表し、何を分母にしたかを確認して再挑戦しましょう。</p>':'<p>Check what one result row means and which denominator is used, then retry.</p>','format'=>FORMAT_HTML],
      'shownumcorrect'=>0,'answer'=>$a,'fraction'=>$r,'feedback'=>$f,'hint'=>[]];
    return question_bank::get_qtype('multichoice')->save_question($q,$form);
}
function v25_rename(int $cid,string $table,string $old,string $new):stdClass{global $DB;$r=$DB->get_record($table,['course'=>$cid,'name'=>$new]);if(!$r){$r=$DB->get_record($table,['course'=>$cid,'name'=>$old],'*',MUST_EXIST);$r->name=$new;if(property_exists($r,'timemodified'))$r->timemodified=time();$DB->update_record($table,$r);}return $r;}

